<script setup>
import {Head,useForm,router} from '@inertiajs/vue3';import Footer from '../Components/Footer.vue';import Errors from '../Components/Errors.vue';import {art} from '../art';
const form=useForm({current_password:'',password:'',password_confirmation:''});
</script><template><Head title="Set your password"/><main class="narrow"><img class="portrait" :src="art.logo" alt="SUSHI"><h1>Make your seat yours.</h1><p>Choose a password of at least eight characters to protect your saved progress.</p><Errors :errors="form.errors"/><form @submit.prevent="form.post('/password',{onFinish:()=>form.reset()})"><label>Current password<input v-model="form.current_password" type="password" autocomplete="current-password" required></label><label>New password<input v-model="form.password" type="password" autocomplete="new-password" minlength="8" required></label><label>Confirm new password<input v-model="form.password_confirmation" type="password" autocomplete="new-password" required></label><button class="primary" :disabled="form.processing">Save password</button><button type="button" class="plain" @click="router.post('/logout')">Sign out</button></form></main><Footer/></template>
